update public.lessons
set content='{"intro": "Esta aula transforma «Caderneta predial e matriz» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "A Caderneta Predial é um documento matricial/fiscal. O formando deve saber identificar artigo e fração, localização, titularidade fiscal, afetação, descrição, ano de inscrição na matriz, Valor Patrimonial Tributário e os campos de área que efetivamente constem. Nos prédios edificados, o artigo 40.º do CIMI distingue área bruta privativa (Aa), áreas brutas dependentes (Ab) e componentes de terreno livre (Ac e Ad) no cálculo fiscal."}, {"title": "Como aplicar na prática", "body": "Leia o documento por blocos: identificação do prédio → titulares fiscais → descrição/afetação → áreas → VPT e dados de avaliação. Nunca converta automaticamente ''área bruta privativa'', ''dependente'', ''implantação'', ''terreno'' ou outras métricas em ''área útil/habitável''. Registe o nome exato do campo e a respetiva fonte."}, {"title": "O que confirmar antes de concluir", "body": "A inscrição matricial serve fins fiscais e não prova, por si só, que uma construção está licenciada, que a configuração física atual está regularizada ou que a titularidade registral coincide com a fiscal. Cruze sempre com Certidão Permanente e, quando relevante, documentação urbanística e plantas."}, {"title": "Exemplo profissional", "body": "Exemplo: a matriz mostra uma área construída superior à que consta de elementos municipais. A resposta profissional não é escolher o maior valor: é assinalar a divergência, perceber a origem e evitar anunciar a área como legalmente consolidada sem validação."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve distinguir factos documentados, informação do cliente, estimativas comerciais e matérias que exigem validação especializada. Quando uma conclusão ultrapassa a sua competência, deve identificá-la como pendente e encaminhá-la."}], "takeaway": "Competência concluída: saber tratar «Caderneta predial e matriz» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: a matriz mostra uma área construída superior à que consta de elementos municipais. A resposta profissional não é escolher o maior valor: é assinalar a divergência, perceber a origem e evitar anunciar a área como legalmente consolidada sem validação."}'::jsonb,
    source_url='https://info.portaldasfinancas.gov.pt/',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=27;
update public.lessons
set content='{"intro": "Esta aula transforma «Certificado energético e outros documentos» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O formando deve reconhecer quando o SCE é aplicável, distinguir certificado de pré-certificado, localizar classe energética, validade e identificação do imóvel, e perceber o impacto na publicidade e na transação."}, {"title": "Como aplicar na prática", "body": "Confirmar que o documento corresponde ao imóvel/fração, verificar validade e classe, conferir se houve alterações relevantes e usar a classe correta na publicidade quando exigida."}, {"title": "O que confirmar antes de concluir", "body": "Não reutilize certificado de outra fração nem trate um documento expirado como atual. Existem exclusões e regras específicas que devem ser confirmadas no SCE."}, {"title": "Exemplo profissional", "body": "Exemplo: anúncio de fração T2 usa o certificado do prédio inteiro. O documento deve ser conferido antes da publicação."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve distinguir factos documentados, informação do cliente, estimativas comerciais e matérias que exigem validação especializada. Quando uma conclusão ultrapassa a sua competência, deve identificá-la como pendente e encaminhá-la."}], "takeaway": "Competência concluída: saber tratar «Certificado energético e outros documentos» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: anúncio de fração T2 usa o certificado do prédio inteiro. O documento deve ser conferido antes da publicação."}'::jsonb,
    source_url='https://www.sce.pt/',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=28;
